"""Paste this cell AFTER offline setup to update the restored training source.
Generated by test/build_kaggle_update.py; does not require Internet.
"""

import base64
from datetime import datetime, timezone
import hashlib
import io
from pathlib import Path
import shutil
import zipfile

PROJECT = Path('/kaggle/working/ECCV')
PAYLOAD_SHA256 = 'cceeb2ce291c8843ef7b82b36e9e9075463917b92b439937199cc3b1eb4b08cb'
PAYLOAD_BASE64 = ''


def main():
    if not (PROJECT / 'clip' / 'bpe_simple_vocab_16e6.txt.gz').is_file():
        raise RuntimeError('Run kaggle_offline.py first; the restored ECCV project is missing.')
    payload = base64.b64decode(PAYLOAD_BASE64)
    if hashlib.sha256(payload).hexdigest() != PAYLOAD_SHA256:
        raise RuntimeError('Update cell was not copied completely: payload checksum mismatch.')
    backup = PROJECT.parent / ('ECCV_source_backup_' + datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S_%f'))
    with zipfile.ZipFile(io.BytesIO(payload)) as archive:
        for record in archive.infolist():
            relative = Path(record.filename)
            target = (PROJECT / relative).resolve()
            if not target.is_relative_to(PROJECT.resolve()) or relative.parts[0] not in {'src', 'test'}:
                raise ValueError('Invalid update path.')
            if target.exists():
                preserved = backup / relative
                preserved.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(target, preserved)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(archive.read(record))
            print('Updated:', relative.as_posix(), flush=True)
    print('Previous source preserved:', backup, flush=True)
    print('Source update complete. Run the training command again.', flush=True)


if __name__ == '__main__':
    main()
